function missingValues(nums: number[]): number[] {
  for (let i = 0; i < nums.length; i++) {
    const v = Math.abs(nums[i]);
    nums[v - 1] = -Math.abs(nums[v - 1]);
  }
  const out: number[] = [];
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] > 0) out.push(i + 1);
    nums[i] = Math.abs(nums[i]); // restore the input
  }
  return out;
}

